// src/components/Admin/Kitchen.js
import React from 'react';
import './Kitchen.css';

function Kitchen({ orders = [], updateOrderStatus, checkFilter, filterBlur }) { 

  const processingOrders = orders.filter(o => o.status === 'processing');
  const doneOrders = orders.filter(o => o.status === 'done');
  
  // Countdown timer logic
  const getProcessingTime = (durationStr) => {
    const time = parseInt(durationStr.split(' ')[0], 10);
    // Simulate time passing on refresh
    const newTime = Math.max(0, time - Math.floor(Math.random() * 3)); 
    if (newTime === 0) {
      return "Served"; 
    }
    return `Ongoing: ${newTime} Min`; // Shows "Ongoing: 14 Min" etc.
  }
  
  // Function to handle the completion of an order
  const handleCompleteOrder = (orderId) => {
      updateOrderStatus(orderId, 'done');
  };

  const renderOrderCard = (order, status) => {
    const isDineIn = order.type === 'Dine In';
    const mainLabel = isDineIn ? order.table : 'Takeaway';
    
    return (
      // Filter applied to the entire card
      <div key={order.id} className={`order-card ${status}`} style={{ filter: checkFilter(order.id) || checkFilter(order.table) ? 'none' : filterBlur }}>
          
          {/* TOP HEADER SECTION */}
          <div className="card-top-header">
              <div className="order-meta-info">
                  <div className="order-icon-wrapper">
                      {/* Icon for the type of order */}
                      <svg viewBox="0 0 24 24" width="20" height="20" fill="currentColor">
                          <path d="M21 5.48c0-.65-.54-1.1-1.19-.94L18 5.61l-5.74-.78c-.53-.08-.96.34-.96.88v14.12c0 .48.3.9.75 1.05l6.5 2.17c.07.02.13.03.2.03.38 0 .7-.27.8-.62L21 21.05V5.48zM9 20.35L2.5 18.27c-.57-.19-.9-.76-.7-1.35.21-.59.78-.92 1.35-.7l6.5 2.17c.57.19.9.76.7 1.35-.21.59-.78.92-1.35.7z"/>
                      </svg>
                  </div>
                  <div className="order-details-wrapper">
                      <span className="order-number">#{order.id}</span>
                      <span className="order-table-time">{mainLabel} | {order.time}</span>
                      <span className="order-item-count">{order.itemCount} Item</span>
                  </div>
              </div>
              
              {/* STATUS BADGE/BUTTON (Top Right) */}
              {status === 'processing' ? (
                  <div className="status-top-badge processing">
                      <span className="type-label">{order.type}</span>
                      <span className="time-label">{getProcessingTime(order.duration)}</span>
                  </div>
              ) : (
                  <div className="status-top-badge done">
                      <span className="type-label">{order.type}</span>
                      <span className="time-label">{isDineIn ? 'Served' : 'Picked Up'}</span>
                  </div>
              )}
          </div>
          
          {/* ITEMS LIST */}
          <div className="order-items-list">
              {order.items && order.items.map((item, idx) => (
                  <div key={idx} className="order-item-kitchen">
                      <span className="item-quantity">{item.quantity} x</span>
                      <span className="item-name">{item.name}</span>
                  </div>
              ))}
              {/* Optional instructions note */}
              {order.instructions && <div className="item-note">{order.instructions}</div>}
          </div>

          {/* BOTTOM ACTION BUTTON */}
          <div className="card-bottom-action">
              {status === 'processing' ? (
                  <button 
                     className="action-button processing"
                     onClick={() => handleCompleteOrder(order.id)}
                  >
                      Processing 
                  </button>
              ) : (
                  <button className="action-button done">
                      Order Done ✓
                  </button>
              )}
          </div>
      </div>
    );
  };

  return (
    <div className="kitchen-container">
      <div className="orders-section">
        <h2>Processing Orders</h2>
        <div className="orders-grid">
          {processingOrders.length > 0 ? (
             processingOrders.map((order) => renderOrderCard(order, 'processing'))
          ) : (
            <p>No orders processing.</p>
          )}
        </div>
      </div>

      <div className="orders-section">
        <h2>Completed Orders</h2>
        <div className="orders-grid">
          {doneOrders.length > 0 ? (
            doneOrders.map((order) => renderOrderCard(order, 'done'))
          ) : (
            <p>No orders completed yet.</p>
          )}
        </div>
      </div>
    </div>
  );
}

export default Kitchen;
